// <diletta-data-cell> — a INSTÂNCIA WEB de `design-system-data-cell`.
//
// É a peça mais usada do BackOffice: 502 instâncias visíveis. No Figma é UM conjunto
// remoto com `Entity` de 11 valores — os "15 componentes" do comentário antigo eram
// nome de CAMADA, que o Figma numera ao duplicar. Aqui o conteúdo é prop e a coluna é
// dado; os quatro `Entity` de edição (input, dropdown, data) não têm par aqui, e a
// razão está declarada em `figma/mapa-web.json`.
import './diletta-avatar.js';

const CONTEUDO = ['texto', 'pessoa', 'estado', 'acao', 'par', 'paragrafo'];
const ALINHAMENTO = ['inicio', 'fim'];

// Da spec, e medida em 100% das 502 instâncias: a célula tem 36 de altura. O
// `paragrafo` é o ÚNICO conteúdo que a faz crescer — e é por isso que o porte
// `historico` da linha tem 64 e não 54.
const ALTURA = 36;

class DilettaDataCell extends HTMLElement {
  static observedAttributes = ['conteudo', 'alinhamento', 'valor', 'subvalor', 'foto'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() {
    this.render();
  }

  attributeChangedCallback() {
    if (this.shadowRoot) this.render();
  }

  get conteudo() {
    const v = this.getAttribute('conteudo');
    return CONTEUDO.includes(v) ? v : 'texto';
  }

  get alinhamento() {
    const v = this.getAttribute('alinhamento');
    return ALINHAMENTO.includes(v) ? v : 'inicio';
  }

  render() {
    const tipo = this.conteudo;
    const valor = this.getAttribute('valor') || '';
    const sub = this.getAttribute('subvalor') || '';
    const cresce = tipo === 'paragrafo';

    let miolo;
    if (tipo === 'pessoa') {
      // Compõe o avatar do DS, não um círculo novo — a mesma regra do chip.
      miolo = `<diletta-avatar nome="${valor.replace(/"/g, '&quot;')}" ` +
        `foto="${(this.getAttribute('foto') || '').replace(/"/g, '&quot;')}" ` +
        `style="--diletta-avatar-tamanho:24px"></diletta-avatar>` +
        `<span class="principal">${valor}</span>`;
    } else if (tipo === 'par') {
      miolo = `<span class="pilha"><span class="principal">${valor}</span>` +
        `<span class="sub">${sub}</span></span>`;
    } else if (tipo === 'acao' || tipo === 'estado') {
      miolo = '<slot></slot>';
    } else {
      miolo = `<span class="principal">${valor}</span>`;
    }

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: block; }
        .celula {
          box-sizing: border-box;
          ${cresce ? '' : `height: ${ALTURA}px;`}
          display: flex; align-items: center; gap: 8px;
          justify-content: ${this.alinhamento === 'fim' ? 'flex-end' : 'flex-start'};
          text-align: ${this.alinhamento === 'fim' ? 'right' : 'left'};
        }
        /* A célula NÃO declara fundo nem borda: quem sabe o estado da linha é a
           linha, e a tarja é dela. */
        .principal { color: var(--cps-fg); }
        .sub { color: var(--cps-textSecondary); }
        .pilha { display: flex; flex-direction: column; min-width: 0; }
        .pilha > * { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
        .paragrafo { white-space: normal; }
      </style>
      <div class="celula ${cresce ? 'paragrafo' : ''}" part="celula">${miolo}</div>`;
  }
}

customElements.define('diletta-data-cell', DilettaDataCell);
export { DilettaDataCell, ALTURA };
